// CoW entry point. Generated by `dia scaffold app CoW`.
//
// Loads assets/cow.diagame via Dia::ApplicationFlow::LoadManifest (compose,
// path aliases, validate), then runs the application loop at 30 Hz.
#include <cstdio>
#include <memory>
#include <DiaApplicationFlow/Application.h>
#include <DiaApplicationFlow/TypeRegistry.h>
#include <DiaApplicationFlow/Manifest/ManifestBootstrap.h>

// Modules register themselves at static init time via DIA_MODULE. The baseline
// modules are force-linked with /WHOLEARCHIVE:CluicheGameBaseline.lib.

#pragma warning(push)
#pragma warning(disable: 6262)  // Application stack frame is large but main() is a one-shot
int main(int /*argc*/, const char* /*argv*/[])
{
    const char* kDiagamePath = "assets/cow.diagame";

    // Heap-allocate the manifest: it grows with module/channel count and can
    // overflow the default 1MB stack once stage manifests are merged in.
    std::unique_ptr<Dia::ApplicationFlow::ApplicationManifestV3> manifestOwner(
        new Dia::ApplicationFlow::ApplicationManifestV3());
    Dia::ApplicationFlow::ApplicationManifestV3& manifest = *manifestOwner;
    Dia::ApplicationFlow::TypeRegistry& registry = Dia::ApplicationFlow::TypeRegistry::Global();

    if (!Dia::ApplicationFlow::LoadManifest(kDiagamePath, manifest, registry))
        return 1;

    Dia::ApplicationFlow::Application app(manifest, registry);

    if (!app.Start())
    {
        printf("Application failed to start\n");
        return 1;
    }

    // Main loop at MainPU frequency (30 Hz). MainPU runs inline here; SimPU and
    // RenderPU run on dedicated threads. Update returns false once every module
    // is inactive (shutdown complete).
    const float kFrameTimeSec = 1.0f / 30.0f;
    while (app.Update(kFrameTimeSec))
    {
    }

    return 0;
}
#pragma warning(pop)
